\begin{theorem}
For sets $A, B \subseteq X$,
$(A \cup B)^{c} = A^{c} \cap B^{c}$.
\end{theorem}

\begin{proof}
For $x \in X$,
\begin{align}
  x \in (A \cup B)^{c} &\iff x \notin A \cup B \\
  &\iff x \notin A \text{ and } x \notin B \\
  &\iff x \in A^{c} \cap B^{c}.
\end{align}
\end{proof}
